INSERT INTO club_category (id, cate_name, logo, description) VALUES
  (1, 'STEM & Innovation', NULL, 'Engineering, robotics, science, and technology-focused clubs.'),
  (2, 'Service & Leadership', NULL, 'Clubs centered on volunteering, civic engagement, and leadership.'),
  (3, 'Creative Arts & Media', NULL, 'Visual arts, performing arts, and multimedia storytelling clubs.'),
  (4, 'Culture & Identity', NULL, 'Clubs organized around heritage, culture, language, and identity communities.'),
  (5, 'Wellness & Athletics', NULL, 'Athletics, physical wellness, recreation, and mental health clubs.'),
  (6, 'Competition & Strategy', NULL, 'Debate, games, olympiads, and strategy-focused clubs.');
INSERT INTO clubs (id, name, slug, alias_name, description, category, meeting_schedule, location, contact_email, advisor, image_url, member_count, achievements) VALUES
  (1, 'Aerospace and Aviation Club', 'aerospace-and-aviation-club', NULL, 'The Aerospace & Aviation Club is a group whose members are interested in learning more about military and civil-grade aircraft, rockets, satellites, and more, and the physics and mathematics behind atmospheric and space flight. We will be doing lots of hands-on activities, such as building planes with various materials, water rockets, and detailed scale models. We will also fly RC planes with FPVs, and host building competitions and trivias within the club. We will have field trips to related institutes and airshows, as well as guest speakers with experience in the aerospace and aviation industries. We will also have service opportunities for members to engage with local communities and share their love for aviation.', 'STEM & Innovation', 'Friday · Weekly · Lunch', 'Room 803', '100029182@mvla.net', 'Mr. Murphy', NULL, 0, '[]'),
  (2, 'AIAS Architecture Club', 'aias-architecture-club', NULL, 'To foster education and appreciation for architecture among MVHS students.', 'STEM & Innovation', 'Thursday · Weekly · Lunch', 'Room 802', '100031964@mvla.net', 'Jared Darby', NULL, 0, '[]'),
  (3, 'Analytics Club', 'analytics-club', NULL, 'The Analytics Club is a vibrant community of sports and stock market enthusiasts dedicated to exploring the realm of data-driven insights. Our primary focus lies in data science and statistics, particularly in sports analytics and stock analytics.', 'STEM & Innovation', 'Wednesday · Weekly · Lunch', 'Room 411', '100032204@mvla.net, 100031823@mvla.net', 'Mr. Alapont', NULL, 0, '[]'),
  (4, 'Artificial Intelligence Club', 'artificial-intelligence-club', NULL, 'The Artificial Intelligence Club is for students curious about the real-world applications and impact of AI on our daily lives. Members will explore fundamental concepts, including linear regression and machine learning algorithms, alongside other crucial topics like AI ethics. We’ll offer hands-on experience with a variety of AI tools, from prompt engineering with large language models like ChatGPT to experiment with generative AI through Google’s AI experiments. Exciting guest speakers will come to share their cutting-edge perspectives, and our members will help organize events and workshops to help teach the broader community about Artificial Intelligence. Our goal is to empower members with a deep understanding of AI and its practical day-to-day use, fostering the next generation of AI-literate leaders.', 'STEM & Innovation', 'Wednesday · Biweekly · Lunch', 'Room 201', '100033313@mvla.net', 'Mr. Alapont', NULL, 0, '[]'),
  (5, 'Asian Pacific Union', 'asian-pacific-union', NULL, 'We aim to celebrate the culture and heritage of Asian Americans and Pacific Islanders, and to ensure that Asian Americans and Pacific Islanders have a unified community and voice at Mountain View High School', 'Culture & Identity', 'Thursday · Biweekly · Lunch', 'Room 210', '100031933', 'Ms. Zarzuela-Borup', NULL, 0, '[]'),
  (6, 'Bring Change to Mind', 'bring-change-to-mind', NULL, 'Bring Change to Mind’s High School Program gives teens a platform to share their voices and raise awareness around mental health. Our goal is to empower students to educate one another, and their communities, and to create a culture of peer support within their schools. Together, we’ll fight the stigma around mental illness. All club members get free access to Headspace to practice mindfulness!', 'Wellness & Athletics', 'Wednesday · Biweekly · Lunch', 'Room 730', '100032830@mvla.net', 'Dr. Wharton', NULL, 0, '[]'),
  (7, 'Chess Club', 'chess-club', NULL, 'The MVHS Chess Club is dedicated to helping members of the community with varying levels of skill and interest in chess to improve at the game while having fun playing. Chess Club includes teaching lessons to beginners, setting up online/local tournaments, and having in-person boards that members can use. Members can come to the chess club during lunch to play and talk with people who share a common interest in the game.', 'Competition & Strategy', 'Monday · Weekly · Lunch', 'Room 706', '100032003@mvla.net', 'Sophia Caramagno', NULL, 0, '[]'),
  (8, 'Computer Science Club', 'computer-science-club', NULL, 'The Computer Science Club aims to provide a space for students of all coding backgrounds to explore computer science. We offer engaging, student-led lessons, collaborative projects, and community events to help members develop programming skills. Our goal is to provide a space for students interested in tech to learn together and engage with like-minded peers in programming projects that address a need or concern in the community.', 'STEM & Innovation', 'Thursday · Weekly · Lunch', 'Room 806', '100032056@mvla.net', 'Ly Nguyen', NULL, 0, '[]'),
  (9, 'Creative Writing Club', 'creative-writing-club', NULL, 'This organization shall have as its objective and purpose to provide a welcoming space where students can explore self-expression through writing, share their work, and inspire one another to grow as writers.', 'Creative Arts & Media', 'Wednesday · Biweekly · Lunch', 'Room 508', '100032881@mvla.net', 'Julie Song', NULL, 0, '[]'),
  (10, 'Crochet Club', 'crochet-club', NULL, 'MVHS Crochet Club shall have as its objective and purpose to allow students who are interested in crocheting to come together and make projects, and also learn how to crochet at a more advanced level. It will also serve to bridge community service and crocheting by facilitating volunteer events with school-wide organizations, as well as external nonprofits.', 'Creative Arts & Media', 'Thursday · Biweekly · Lunch', 'Room 109', '100032174@mvla.net', 'Lori Nock', NULL, 0, '[]'),
  (11, 'DERM Club', 'derm-club', NULL, 'The Dermatology Education Research Mission (DERM) club seeks to educate Mountain View High School students about the integumentary system, raise awareness of skin health, and inspire curiosity in dermatology through education, hands-on activities, and community engagement.', 'STEM & Innovation', 'Thursday · Biweekly · Lunch', 'Room 117/120', '100031861@mvla.net', 'Jenna Adams', NULL, 0, '[]'),
  (12, 'Drama Llamas', 'drama-llamas', NULL, 'Drama Llamas is an entirely student-run club that puts on a full-scale musical at the end of each school year. The show is directed, teched, choreographed, managed, produced, performed, and sometimes even written by students of Mountain View High School. We were founded with the intent of making all aspects of theatre available to everyone, regardless of past experience. We are committed to creating student-run theater and learning leadership skills.', 'Creative Arts & Media', 'Monday, Wednesday, Thursday, Friday · Weekly · After School', 'Room 125', '100034110@mvla.net', 'Anthony Gallego', NULL, 0, '[]'),
  (13, 'Dream Volunteers Club', 'dream-volunteers-club', NULL, 'The dream volunteers club is a club for people who want a way to give back to their community. It is based on the organization Dream Volunteers, who organize service trips to other countries. Our members do not have to go on any trips, but can have the oppurtunity, and will learn about and particiapte in outside of school volunteer oppurtunies dicsovered by us.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 604', '100033849@mvla.net', 'Stucker', NULL, 0, '[]'),
  (14, 'Economics Club', 'economics-club', NULL, 'The Economics Club is a community of students curious about how societies allocate resources and make choices. We emphasize the broader study of economic systems, policies, and theories (from supply and demand to global trade). Through case studies, and debates on current events, members can learn to think critically about how economic forces shape the world. Our goal is to build a foundation in both microeconomics and macroeconomics while connecting theory to real-world issues. In addition, we participate in the National Economics Challenge, where students apply their knowledge of core principles and analytical reasoning in a competitive setting.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 609', '100032162@mvla.net', 'Rachael Roach', NULL, 0, '[]'),
  (15, 'F=ma Club', 'f-ma-club', NULL, 'The F=ma club is a group whose members are focused on studying for the F=ma exam, which is taken in February, in hopes of qualifying for USAPhO. Our members work together during meetings to learn new concepts and solve problems together to improve their test-taking skills. Members learn advanced physics problem solving techniques and apply them to practice tests and past F=ma problems.', 'Competition & Strategy', 'Monday · Weekly · Lunch', 'Room 617', '100029182@mvla.net', 'Mr. West', NULL, 0, '[]'),
  (16, 'Fellowship of Christian Athletes (FCA)', 'fellowship-of-christian-athletes-fca', NULL, 'To spread the Gospel of Jesus Christ to all people in the world, through athletes and coaches.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 724', '100034145@mvla.net', 'Tim Lugo', NULL, 0, '[]'),
  (17, 'Fentanyl and Substance Awareness Club', 'fentanyl-and-substance-awareness-club', NULL, 'Our club is dedicated to raising awareness about the dangers of fentanyl and substance misuse within our community through education, open conversation, and compassionate support. We strive to educate individuals with life-saving knowledge, including recognizing the signs of overdose and the importance of harm reduction tools like naloxone and narcan, while breaking down the stigma that too often prevents people from seeking help by teaching about the Good Samaritan laws. By fostering a safe and judgment-free space, we aim to empower our members to make informed decisions, support those affected by substance use, and be advocates for a healthier, more informed community.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 116', '100033287@mvla.net', 'Jeff Panos', NULL, 0, '[]'),
  (18, 'French Club', 'french-club', NULL, 'The mission of the French Club is to celebrate the uniqueness and beauty of French culture and traditions and spread it to our surrounding community, in a way that is accommodating of all. This is done through the celebration of French holidays, the honoring of French art, and the playing of French games.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 603', '100032256@mvla.net', 'Madame Gres', NULL, 0, '[]'),
  (19, 'French Honors Society', 'french-honors-society', NULL, 'The French Honors Society (SHF) is a group whose members are devoted to studying the French Language and Culture. Members, all of whom participate in French 3H or above, are strong students who are interested in learning more about the culture and developing speaking skills through group activities.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 603', '100032256@mvla.net', 'Madame Gres', NULL, 0, '[]'),
  (20, 'Girls Who Code Club', 'girls-who-code-club', NULL, 'The Girls Who Code Club works to foster an environment in which women in technology at MVHS feel welcome and comfortable to develop their coding skills and to teach members of the community more about computer science through lessons in coding and attending fun events like hackathons. We work towards small-scale individual projects and group projects where club members develop their own websites and teach code at local middle schools.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 801', '100031930@mvla.net', 'Mrs. Winawer', NULL, 0, '[]'),
  (21, 'Information Security Club', 'information-security-club', NULL, 'The Information Security Club is dedicated to educating students about various aspects of offensive and defensive information security. To give back to the community, some community projects that the club participates in include contributing code to make free and open source software, and contributing writeups/tutorials online to assist beginning information security students.', 'STEM & Innovation', 'Wednesday · Weekly · Lunch', 'Room 513', '100032056@mvla.net', 'Jennifer Chiu', NULL, 0, '[]'),
  (22, 'Japanese Culture Club', 'japanese-culture-club', NULL, 'The Japanese Culture Club is a club with the main goal of spreading and appreciating Japanese culture on the MVHS campus. Through activities and meetings, Mountain View students have the opportunity to experience and learn more about Japanese culture.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 601', '100032524@mvla.net', 'Minako Walther', NULL, 0, '[]'),
  (23, 'Jewish Student Union', 'jewish-student-union', NULL, 'Providing a safe meeting space and community for Jewish students of MVHS, and inviting other students to learn about Jewish history, culture, etc.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 728', '100033661@mvla.net', 'Mr. Heiken', NULL, 0, '[]'),
  (24, 'K-Pop Dance Club', 'k-pop-dance-club', NULL, 'This club''s objective and purpose is to bring students together through a shared love of K-pop, while providing opportunities to learn choreography, improve dance skills, and enjoy the experience of dancing in a fun and supportive environment.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 517', '100032180@mvla.net', 'Ms. Kato', NULL, 0, '[]'),
  (25, 'Leo Club', 'leo-club', NULL, 'The Leo Club is a philanthropy/community service club where our members who enjoy volunteering can give back to their community by joining and participating in our club events. Students part of the Leo Club will have the opportunity to plan and interact in fun, diverse, and inclusive community service projects such as trash pick-up, beach cleaning, senior tech events, bicycle repair, and more. We are also part of a parent organization, called the Lions Club, which is a non-profit organization dedicated to giving back through community service.', 'Service & Leadership', 'Wednesday, Friday · Biweekly · Lunch', 'Room 609 or 729', '100032686@mvla.net', 'Dr. Yick and Prof Roach', NULL, 0, '[]'),
  (26, 'M1820 Christian Club', 'm1820-christian-club', NULL, 'M1820 exists to encourage Christians to boldly live out their faith on school grounds. It is our mission to disciple believers and equip them with the wisdom and passion that is necessary for them to then go out and spread the values of faith, hope, and charity to the greater community, starting here at MVHS.', 'Service & Leadership', 'Friday · Weekly · Lunch', 'Room 125', '100031869@mvla.net', 'Mr. Gallego', NULL, 0, '[]'),
  (27, 'Marine Biology and Ocean Conservation Club', 'marine-biology-and-ocean-conservation-club', NULL, 'This organization shall have as its objective and purpose to educate students about marine science, raise awareness surrounding the impacts of climate change on our oceans, and encourage members to complete community service to our local marine ecosystems.', 'STEM & Innovation', 'Thursday · Biweekly · Lunch', 'Room 117', '100033213@mvla.net', 'Katie Sheldon', NULL, 0, '[]'),
  (28, 'Math Club', 'math-club', NULL, 'The Math Club focuses on competitive and proof-based math outside of the school framework. We prepare students to succeed in math competitions. Members of the club also help teach competition math to students at Blach and Graham.', 'STEM & Innovation', 'Wednesday · Weekly · Lunch', 'Room 103', '100032003@mvla.net, 100033492@mvla.net', 'Annie Liu', NULL, 0, '[]'),
  (29, 'MEChA', 'mecha', NULL, 'Our mission as M.E.Ch.A is to foster positive change and revive our old club''s history within the community by standing up for educational policy changes that encourage equitable representation and amplify Latinx voices in our educational community; addressing the challenges Latinx and other groups face in educational and communal aspects. We are dedicated to creating a more inclusive and just society where students of all kinds of backgrounds are recognized and provided with the opportunities and resources they have long deserved.', 'Culture & Identity', 'Thursday · Biweekly · Lunch', 'Library', '100031798@mvla.net', 'Ms. Kemos', NULL, 0, '[]'),
  (30, 'Model UN', 'model-un', NULL, 'This organization shall serve the students of Mountain View and provide them with a stronger understanding of the United Nations. Attending MUN conferences, learning about diplomacy and promoting real life civic engagement.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 706', '100034069@mvla.net', 'Ms Caramagno', NULL, 0, '[]'),
  (31, 'Mountain View High School Science Olympiad', 'mountain-view-high-school-science-olympiad', NULL, 'The MVHS Science Olympiad club educates and inspires students in all STEM (science, technology, engineering, and math) disciplines through hands-on activities.', 'STEM & Innovation', 'Friday · Weekly · After School (6:30 - 9:30)', 'Room 617', '100032279@mvla.net, 100032037@mvla.net', 'Jack West, Anthony Gallego', NULL, 0, '[]'),
  (32, 'Mountain View Los Altos Speech & Debate', 'mountain-view-los-altos-speech-debate', NULL, 'At MVLASD, we believe Speech and Debate (also known as “forensics”) is one of the most valuable activities a student can participate in. Participants develop research skills, strategies that will help them on standardized tests, and the ability to speak in front of large groups with poise and confidence. Students also see dramatic improvements in writing organization, clarity and concision of speech and prose, and the ability to think quickly, critically, and from multiple perspectives. Students learn to set goals, delineate the steps needed to achieve them, and then hit the ground running! Students make lifelong friends in speech and debate! High school is a critical period for developing social connections, and forensics students often say speech and debate feels like a second home to them. Please check out our website: mvlasd.club for more information.', 'Competition & Strategy', 'Monday, Wednesday · Weekly · After School', 'Library/Zoom', '100032533@mvla.net', 'Julie Herman', NULL, 0, '[]'),
  (33, 'Muslim Student Association (MSA)', 'muslim-student-association-msa', NULL, 'To connect all students through cultural events, celebrations, and learning about Islam, while building a strong Muslim community at MVHS.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 720', '100032312@mvla.net', 'Mr. Ortiz', NULL, 0, '[]'),
  (34, 'MVHS BMES', 'mvhs-bmes', NULL, 'MVHS BMES is a club dedicated to pursuing the interdisciplinary field of biomedical engineering. Our club primarily focuses on connecting with the field through guest speakers, labs, and other hands on activities. We also plan to participate in the Samsung Solve for Tomorrow competition, a design challenge where we compete against students across the nation.', 'STEM & Innovation', 'Thursday · Biweekly · Lunch', 'Room 617', '100033981@mvla.net, 100033397@mvla.net', 'Abigail Stucker', NULL, 0, '[]'),
  (35, 'MVHS Driver''s Association', 'mvhs-driver-s-association', NULL, 'The MVHS Driver’s Association seeks to eradicate the confusion around the process of getting a drivers license that prevents many from doing so. By spreading information and resources on how to get a drivers license, we provide students with opportunities to learn where, how, and when to get one. We also teach car maintenance skills and basics, and help students prepare for their permit and license tests. We are open to all, regardless of driving experience, who want to learn, teach, or just have fun.', 'Service & Leadership', 'Wednesday · Biweekly · Lunch', 'Room 115', '100031957@mvla.net', 'Simon Huynh', NULL, 0, '[]'),
  (36, 'MVHS Green Team', 'mvhs-green-team', NULL, 'Here at GreenTeam, we are dedicated to fostering a culture of environmental responsibility within our school and local community. From organizing impactful tree planting campaigns to leading beach clean-ups, we strive to inspire positive changes around MVHS campus and promote a greener, more sustainable future.', 'Service & Leadership', 'Wednesday · Weekly · Lunch', 'Room 117', '100032861@mvla.net', 'Jenna Adams', NULL, 0, '[]'),
  (37, 'MVHS Jazz and Composition Club', 'mvhs-jazz-and-composition-club', NULL, 'The organization shall have as its purpose to teach students about jazz music, its history, and provide them a space to play it.', 'Service & Leadership', 'Thursday · Biweekly · Lunch', 'Packard Hall', '100032063@mvla.net', 'Ricky Alegria', NULL, 0, '[]'),
  (38, 'MVHS Makers With A Mission', 'mvhs-makers-with-a-mission', NULL, 'Join our creative and community-driven makers club where we combine art and engineering, to make a difference! We will be designing and building 3D projects using cardboard, fabric, sculpting and 3D printer designs, offering personalized creations to take home and for low-income kids, individuals with disabilities, and senior centers. This club is open to artists, creative individuals, engineers, and anyone eager to meet a new community. No matter your skill level, there is a place for you in this makers club!', 'STEM & Innovation', 'Wednesday · Biweekly · Lunch, We meet Tuesdays at lunch (there was no option to pick it!)', 'Room 127', '100032293@mvla.net', 'Kristin Cardenas', NULL, 0, '[]'),
  (39, 'MVHS Red Cross Club', 'mvhs-red-cross-club', NULL, 'The MVHS Red Cross Club will work to continue the mission of the Red Cross and work to improve the lives of people in our community and the rest of the world. Members are given the opportunity to help supply people in need of toiletries and blankets, support communities recovering from a disaster and learn about blood health and blood donation. We will also improve our school community by educating about preparedness to help themselves and others in the event of a disaster.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 110', '100033998@mvla.net', 'Meghan Engle', NULL, 0, '[]'),
  (40, 'MVHS Women in STEM', 'mvhs-women-in-stem', NULL, 'MVHS Women in STEM (WiSTEM) empowers women to explore and pursue interests and careers in STEM fields, addressing the gender imbalance with a significant underrepresentation of women. In hopes of increasing the amount of women who go into STEM each year, we will provide an inclusive and supportive space for learning and mentorship that would give MVHS students the encouragement they need. Working alongside the larger Women in STEM organization, we will focus on community outreach through hands-on activities, STEM events, and guest speakers for the local youth and students of Mountain View, as well as nearby communities. Although our mission centers on uplifting women, we welcome all to join in our fun and educational meetings and be part of the process of creating a more diverse community for STEM.', 'Service & Leadership', 'Thursday · Biweekly · Lunch', 'Room P4', '100034056@mvla.net, 100033592@mvla.net', 'Ms. Babiak', NULL, 0, '[]'),
  (41, 'Owed Soap', 'owed-soap', NULL, 'Our mission is to create as many soaps as possible per year from used, purified cooking oil to donate to homeless shelters while also helping our environment little by little.', 'Service & Leadership', 'Monday · Biweekly · Lunch', 'Room 703', '100033253@mvla.net, 100033327@mvla.net', 'Ms. Boyle', NULL, 0, '[]'),
  (42, 'Psychology Club', 'psychology-club', NULL, 'The MVHS Psychology Club aims to promote appreciation for all disciplines of psychology through engaging lessons, hosting fun activities like student surveys, and cultivating a safe space to talk about mental illnesses. Through weekly meetings, members will have the opportunity to learn about psychology career pathways; the importance of mental health; how psychology affects our thoughts, behavior, and the world around us on a daily basis; and how we can use psychology to improve ourselves. We will feature a new psychology concept spotlight article weekly on our website. We welcome all students.', 'Wellness & Athletics', 'Wednesday · Biweekly · Lunch', 'Room 723', '100032154@mvla.net', 'Paul McHenry', NULL, 0, '[]'),
  (43, 'Puzzle Club', 'puzzle-club', NULL, 'The Puzzle Club is a group whose members enjoy solving puzzles such as sudoku, crosswords, escape rooms, logic problems, mystery hunt puzzles, and other fun brain challenges. The club aims to bring together like-minded people to encourage collaborative puzzle solving and foster a puzzling community. We plan on participating as a team in multiple national events, prepare members for individual competitions, and host local events such as escape room trips.', 'Competition & Strategy', 'Friday · Biweekly · Lunch', 'Room P2', '100032056@mvla.net', 'Param Singh', NULL, 0, '[]'),
  (44, 'Rock climbing club', 'rock-climbing-club', NULL, 'To bring and teach students to climb', 'Wellness & Athletics', 'Thursday · Biweekly · Lunch', 'Room 513', '100033609@mvla.net', 'Ms. Chiu', NULL, 0, '[]'),
  (45, 'SLAM Magazine', 'slam-magazine', NULL, 'SLAM Magazine is an organization and independent student-run publication that is dedicated to illuminating social justice issues in our community that don''t receive mainstream attention. We strive to provide insight and understand the complexities behind systems of oppression based on race, ethnicity, gender, ability, and other identities through the arts. For our team members, our organization provides career-applicable skills and experience in design, photography, media marketing, business, and writing/journalism. Students work with their teams and as an organization to produce two issues annually that get distributed throughout the MVLA community.', 'Service & Leadership', 'Wednesday · Weekly · After school (3:10-4:10)', 'Room 109', '100032189@mvla.net', 'Lori Nock', NULL, 0, '[]'),
  (46, 'South Asian Student Union', 'south-asian-student-union', NULL, 'The South Asian Student Union is a club where members will learn about South Asian heritage, traditions, modern adaptations/stereotypes of South Asian Nations and also share their experiences as South Asians in America. Our club hopes to unite the South Asian community in Mountain View High School and to build self pride and confidence in their ethnicity and culture. However, we appeal to both those who identify with South Asian culture and those who wish to learn about South Asian culture.', 'Culture & Identity', 'Thursday · Biweekly · Lunch', 'Room 726', '10031910@mvla.net', 'Felitia Hancock', NULL, 0, '[]'),
  (47, 'Spartan Buddies', 'spartan-buddies', NULL, 'Spartan Buddies at MVHS unites special needs students in our special education and Life Skills program with neurotypical MVHS students in the hopes of creating genuine friendship connections and increasing inclusivity at school. For peers with special needs, feeling different and excluded is an everyday experience. The simple action of pairing students with their Spartan Buddy and encouraging them to have genuine conversations while guiding them with fun activities can be life changing for them. It can develop intense feelings of belonging and overall joy in these students, and that is more important than we as neurotypical individuals may ever understand.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 708', '100032253@mvla.net', 'Seamus Quillinan', NULL, 0, '[]'),
  (48, 'Spartan Equity Partners', 'spartan-equity-partners', NULL, 'The Spartan Equity Partners Club is a dedicated group of members who are passionate about learning the ways of finance and investing, and are dedicated to pursuing a higher level of financial literacy education. Our Mission is to expose our members to new perspectives on building wealth by teaching insightful strategies and models that they can use for themselves or for the club. Using our club experience in the past, we seek to expand financial education to more members of the Mountain View Community in hopes of them succeeding in their futures.', 'Competition & Strategy', 'Friday · Biweekly · Lunch', 'Room 510', '100032546@mvla.net', 'Juan Alvarez', NULL, 0, '[]'),
  (49, 'Steam Club', 'steam-club', NULL, 'Our club aims to help promote the fun and learning of science for elementary school kids. We will do this by reaching out to elementary schools and helping craft fun science lessons and show the magic of science', 'STEM & Innovation', 'Wednesday · Biweekly · Lunch', 'Room 120', '100033221@mvla.net', 'Christine Yow', NULL, 0, '[]'),
  (50, 'Taiwanese American Student Association', 'taiwanese-american-student-association', NULL, 'The Taiwanese American Student Association (TASA) aims to build a safe and inclusive environment at Mountain View High School where members are able to share their cultural experiences in Taiwan. This club will educate students on a culture not often talked about. The Taiwanese American Student Association will also benefit each member’s communication and speaking skills. Some topics we will cover include local attractions, different cities, and Taiwanese food.', 'Culture & Identity', 'Friday · Biweekly · Lunch', 'Room 513', '100034154@mvla.net', 'Jennifer Chiu', NULL, 0, '[]'),
  (51, 'TEDxMVHS', 'tedxmvhs', NULL, 'TEDxMountainViewHighSchool is a student-led club dedicated to inspiring and empowering others through the sharing of “ideas worth spreading.” We organize an official, full-day TEDx event with 1400+ students in attendance, featuring talks on diverse topics and fostering a culture of curiosity within our community. Our members are passionate about creating platforms for meaningful discussions and creative thinking. As a part of our annual TEDxMVHS event, MVHS students engage in interactive activities and audition for the opportunity to present their ideas to the public.', 'Service & Leadership', 'Thursday · Biweekly · Lunch', 'Room P11', '100032533@mvla.net', 'Jyoti Reid', NULL, 0, '[]'),
  (52, 'The Pediatrics Club', 'the-pediatrics-club', NULL, 'The Pediatrics Club is a club in which participants will engage in lectures, activities, and labs concerning various areas of Pediatrics. For instance, our club will explore the fields of pediatric cardiology, pediatric neurology, and pediatric surgery. Our club would happily accept donations of synthetic dissection kits, surgical and dissection tools, children''s toys, and silicone human model pads. Our community events consist of “Adopt a teddy bear donation fair”, collecting books and toys for the children''s hospital, painting cups to donate to children''s hospitals, and hosting a children’s introduction to healthcare fair.', 'STEM & Innovation', 'Wednesday · Biweekly · Lunch', 'Room 703', '100033684@mvla.net, 100033586@mvla.net', 'Heather Boyle', NULL, 0, '[]'),
  (53, 'Theater Club', 'theater-club', NULL, 'The Theatre Club is a club that meets weekly on Wednesdays to celebrate the community and culture surrounding theatre. We celebrate the community through lunch activities such as improv games, watching musicals, and generally chatting about recent theatre news. We also celebrate theatre culture outside of school through musical theatre Cabarets and going Scaroling during Halloween. The Theatre Club also provides a place to be rewarded for theatre experience out our school through ITS and awards that come from theatre participation.', 'Service & Leadership', 'Wednesday · Weekly · Lunch', 'Acting Classroom', '100031875@mvla.net', 'Pancho Morris', NULL, 0, '[]'),
  (54, 'Ukrainian Culture Club', 'ukrainian-culture-club', NULL, 'The Ukrainian Culture Club is a group whose members are interested all aspects of Ukrainian Culture. We hope to share the beauty of Ukrainian food, dance, clothing, and artistry. We will also look for opportunities to support humanitarian relief efforts in Ukraine.', 'Service & Leadership', 'Thursday · Biweekly · Lunch', 'Room 721', '100032037@mvla.net, 100031715@mvla.net', 'Kristin Cardenas', NULL, 0, '[]'),
  (55, 'Unhoused Awareness', 'unhoused-awareness', NULL, 'Our club''s purpose is to support and advocate for people experiencing unhoused in our community by participating in drives, making blankets, creating cards for those in foster care, and more.', 'Service & Leadership', 'Friday · Biweekly · Lunch', 'Room 704', '100032253@mvla.net', 'Danie Robledo', NULL, 0, '[]'),
  (56, 'Vietnamese Student Association (VSA)', 'vietnamese-student-association-vsa', NULL, 'We are driven to teach high school students about Vietnamese culture. These shall include lessons on culture, history, music, games, language, and organizing supply drives to support the Vietnamese community.', 'Culture & Identity', 'Thursday · Monthly · Lunch', 'Room 612', '100032251@mvla.net', 'David Campbell', NULL, 0, '[]'),
  (57, 'Women Athlete''s Club', 'women-athlete-s-club', NULL, 'The Women Athlete''s Club aims to promote connection and wellness through creating a space where athletes are welcome to share their experiences and learn about nutrition, recovery methods, injury prevention, and competitive mindset. This community will help student athletes learn to balance school and sports while succeeding in both and still prioritizing well-being.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room P8', '100033123@mvla.net', 'Taran Sun', NULL, 0, '[]'),
  (58, 'Youth Hunger Initiative', 'youth-hunger-initiative', NULL, 'We are a group of students dedicated to help fight hunger in our community. Our members will volunteer at soup kitchens, distribute food to those in need, spread awareness and host food drives. We work with kindness and compassion to provide steps to fight hunger in our world today.', 'Service & Leadership', 'Monday · Weekly · Lunch', 'Room 724', '100033343@mvla.net', 'Ms. Burmeister', NULL, 0, '[]');
